function slugifyCustomArrayKey(value) {
  return (
    cleanText(value, 'items')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '_')
      .replace(/^_+|_+$/g, '') || 'items'
  );
}

function lessonTitle(lesson, lessonNumber) {
  return `Lesson ${lessonNumber}: ${stripLessonPrefix(lesson?.title || lesson?.lessonTitle || lesson?.lt || '') || `Topic ${lessonNumber}`}`;
}

function extractColumn(lesson, key) {
  const sections = Array.isArray(lesson?.sections) ? lesson.sections : [];
  const extractor = COLUMN_EXTRACTORS[key];
  if (!extractor) return '';
  return extractor.extract(sections);
}

function wordsFromConcepts(values, limit = 8) {
  const stopWords = new Set([
    'and',
    'for',
    'the',
    'with',
    'from',
    'into',
    'about',
    'using',
    'students',
    'student',
    'course',
    'lesson',
    'week',
    'will',
    'able',
    'their',
    'this',
    'that',
    'through',
    'apply',
    'analyze',
    'evaluate',
    'create',
    'what',
    'why',
    'how',
    'matters',
    'overview',
    'introduction',
    'intro',
  ]);
  // Emit multi-word phrases, never bare title tokens: splitting on whitespace
  // turned "Climate Science, Justice Frameworks" into fake concepts like
  // "Climate" and "Frameworks" that read as word salad in compiled prose.
  const candidates = values
    .filter(Boolean)
    .flatMap((value) =>
      String(value)
        .split(/\n|;|\||•|:|,|\(|\)|–|—|\band\b|\bor\b|\bversus\b|\bvs\.?\b/i)
        .map((part) => stripListPrefix(part))
        .map((part) => {
          const stemStripped = part.replace(OBJECTIVE_STEM_LEAD_RE, '');
          if (stemStripped !== part) {
            // v0.14.3 C1: hypothesized dead on graph path (graph concepts
            // arrive typed, never as objective prose) — delete after
            // live-round proof.
            recordLegacyPathHit('objective-stem-strip', part);
          }
          return stemStripped
            .replace(
              /\s+(?:in|for|across|within|through)\s+(?:context|course activities|this course|the course)\.?$/i,
              '',
            )
            .replace(/[.!?]+$/, '')
            .trim();
        }),
    )
    .filter((phrase) => {
      if (!phrase) return false;
      const words = phrase.split(/\s+/);
      if (words.length > 6) return false;
      if (words.every((word) => word.length <= 3 || stopWords.has(word.toLowerCase()))) return false;
      if (/^\d/.test(phrase)) return false;
      return phrase.length > 3;
    });
  return unique(candidates, limit);
}

const OBJECTIVE_STEM_LEAD_RE =
  /^(?:students?\s+(?:will\s+)?(?:be\s+able\s+to\s+)?)?(?:define|explain|describe|analyze|evaluate|create|design|compare|apply|synthesize|formulate|interpret|critique|develop|construct|identify|use|build|examine|assess|distinguish|differentiate|calculate|solve|predict|recognize|prioritize|review|practice|connect|integrate|demonstrate|combine|classify|organize|summarize|investigate|explore|justify|relate|revise)\s+/i;

function isQuestionLikeTitle(value) {
  return /^(?:what|why|how|when|where|who)\b/i.test(cleanText(value)) || /\b(?:and why|why it matters)\b/i.test(value);
}

const OBJECTIVE_IMPERATIVE_VERB_RE =
  /^(?:analyze|evaluate|create|design|explain|compare|apply|synthesize|formulate|interpret|critique|develop|construct|identify|describe|use|integrate|connect|demonstrate|distinguish|examine|assess|review|practice|build|combine|classify|organize|summarize|investigate|explore|justify|relate|revise)\b/i;

// v0.14.1: an objective sentence with a comma list ("Integrate mineral,
// rock, and process concepts") is a command, not comma-separated terms —
// splitting it shipped fragments like "Integrate mineral" as key terms.
function isObjectiveSentenceValue(value) {
  const text = cleanText(value);
  if (!/^[A-Z]/.test(text) || !OBJECTIVE_IMPERATIVE_VERB_RE.test(text)) return false;
  const commaIndex = text.indexOf(',');
  return commaIndex !== -1 && /\b(?:and|or)\s+\S/i.test(text.slice(commaIndex));
}

function splitConceptValues(value) {
  return splitList(value).flatMap((item) => {
    const text = cleanText(item);
    if (isObjectiveSentenceValue(text)) return [text];
    const parts = text
      .split(/,\s*/)
      .map((part) => part.trim().replace(/^(?:and|or)\s+/i, ''))
      .filter(Boolean);
    if (parts.length > 1) {
      // v0.14.3 C1 hypothesis ("dead on graph path — graph concepts arrive
      // typed") FALSIFIED by the live v0.14.5 rounds: 36 hits across 10/11
      // graph-path courses (round 2026-06-11T20-21; e.g. "Solstices,
      // equinoxes, and seasonal markers"). Model-authored concept/topic
      // strings carry comma lists the fixture corpus never did — the
      // splitter is LOAD-BEARING on the live graph path and stays. No
      // provenance signal reaches this pure helper, so the hit records
      // unconditionally; fixture classes attribute it in the diet matrix.
      recordLegacyPathHit('concept-comma-split', text);
    }
    return parts;
  });
}

function isObjectiveLikeConcept(value) {
  const text = cleanText(value);
  if (isObjectiveSentenceValue(text)) return true;
  return OBJECTIVE_IMPERATIVE_VERB_RE.test(text) && wordCount(text) > 4;
}

function isOverlongConceptCandidate(value) {
  const text = cleanText(value);
  return wordCount(text) > 7 || (/[.!?]$/.test(text) && wordCount(text) > 3);
}

function isOverbroadLessonTitleConcept(value, title) {
  const text = cleanText(value);
  const titleText = stripLessonPrefix(title || '');
  if (!text || !titleText || text.toLowerCase() !== titleText.toLowerCase()) return false;
  return wordCount(text) > 6 || isQuestionLikeTitle(text);
}

// v0.14.1 round-2 (fix 3b): internal portfolio-thread artifacts — minted
// evidence-packet descriptors ("<packet> for Lesson 5: <topic>") or anything
// naming an "evidence packet" — must never bind into a concept/topic slot
// (the live Week 5 success criterion read "Names the relevant Lesson 5
// evidence packet concept accurately"). Excluded here so every concept
// consumer falls back to the section topic instead.
function isEvidencePacketLikeConcept(value) {
  const text = cleanText(value);
  return /\bevidence packet\b/i.test(text) || /\bfor Lesson \d+\s*:|:\s*Lesson \d+\b/i.test(text);
}

function normalizeConceptCandidates(values, { title = '', limit = 8 } = {}) {
  const candidates = unique(
    asArray(values)
      .flatMap((value) => splitConceptValues(value))
      .map((value) => normalizeObjectiveText(value))
      .filter(
        (value) =>
          value &&
          !isWeakConcept(value) &&
          !isObjectiveLikeConcept(value) &&
          !isOverlongConceptCandidate(value) &&
          !isOverbroadLessonTitleConcept(value, title) &&
          !isEvidencePacketLikeConcept(value) &&
          !isUnsafeLessonConceptPhrase(value),
      ),
    limit * 2,
  );
  // Substring-dedupe: "Camera Style" adds nothing next to "Cinematography and
  // Camera Style". Prefer the longer phrasing — replace a kept substring when
  // a superstring arrives, skip candidates already covered.
  const kept = [];
  for (const candidate of candidates) {
    const lower = candidate.toLowerCase();
    const coveredBy = kept.findIndex((existing) => existing.toLowerCase().includes(lower));
    if (coveredBy !== -1) continue;
    const covers = kept.findIndex((existing) => lower.includes(existing.toLowerCase()));
    if (covers !== -1) {
      kept[covers] = candidate;
      continue;
    }
    kept.push(candidate);
  }
  return kept.slice(0, limit);
}

function firstNonEmpty(...values) {
  return values.map((value) => cleanText(value)).find(Boolean) || '';
}

function joinCriteriaSentence(criteria = []) {
  const parts = asArray(criteria)
    .map((criterion) => stripTerminalPunctuation(criterion))
    .filter(Boolean)
    .map((criterion) => criterion.charAt(0).toLowerCase() + criterion.slice(1));
  if (parts.length === 0) return 'meets the published success criteria.';
  return `${parts.join('; ')}.`;
}

function sanitizeAssignmentParameterForStudent(value) {
  return stripTerminalPunctuation(value)
    .replace(/\b(\d+)\s*(?:-|–|—|\bto\b)\s*(\d+)\s+sections\b/gi, '$1-$2 labeled parts')
    .replace(/\b(\d+)\s+sections\b/gi, '$1 labeled parts')
    .replace(
      /\bsections?\s+(?:of|for)\s+the\s+(?:brief|submission|artifact|report|portfolio)\b/gi,
      'parts of the submission',
    )
    .replace(/^use brief written explanations$/i, 'write brief explanations')
    .replace(/^include at least (\d+) misconceptions$/i, 'address at least $1 common misunderstandings')
    .replace(/^focus on (.+)$/i, 'connect $1 to the submitted evidence')
    .replace(/^support answers with reasons$/i, 'justify each answer with a reason')
    .replace(/^include process and outcome$/i, 'show both process and outcome')
    .replace(/\s+/g, ' ')
    .trim();
}

function assignmentCoreParametersForStudent(lesson) {
  return (lesson?.enrichment?.assignmentCore?.parameters || [])
    .map((parameter) => sanitizeAssignmentParameterForStudent(parameter))
    .filter(Boolean);
}

