function singularIdentityToken(token) {
  if (/ies$/.test(token) && token.length > 4) return `${token.slice(0, -3)}y`;
  if (/s$/.test(token) && token.length > 4) return token.slice(0, -1);
  return token;
}

function identityTokens(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/-/g, ' ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .map((token) => singularIdentityToken(token))
    .filter((token) => token.length >= 4 && !ENRICHMENT_IDENTITY_STOPWORDS.has(token));
}

function lessonIdentityTokenSet(lesson = {}) {
  return new Set(
    [
      stripLessonPrefix(lesson.title || ''),
      ...(lesson.keyConcepts || []),
      ...(lesson.outcomes || []),
      lesson.studentArtifact,
      lesson.assessmentLink,
    ].flatMap(identityTokens),
  );
}

function highRiskEnrichmentIdentityTokenSet(enrichment = {}) {
  if (!enrichment || typeof enrichment !== 'object') return new Set();
  return new Set(
    [
      enrichment.title,
      enrichment.topic,
      enrichment.focus,
      enrichment.assignmentCore?.taskDescription,
      ...(enrichment.assignmentCore?.parameters || []),
      enrichment.scenario?.title,
      enrichment.scenario?.prompt,
      enrichment.discussionPrompt?.prompt,
    ].flatMap(identityTokens),
  );
}

function enrichmentMatchesLessonIdentity(lesson = {}, enrichment = null) {
  if (!enrichment || typeof enrichment !== 'object') return true;
  const lessonTokens = lessonIdentityTokenSet(lesson);
  const highRiskTokens = highRiskEnrichmentIdentityTokenSet(enrichment);
  if (lessonTokens.size === 0 || highRiskTokens.size === 0) return true;
  return [...highRiskTokens].some((token) => lessonTokens.has(token));
}

function blueprintDomainText(blueprint = {}) {
  return cleanText(
    [
      blueprint.courseName,
      blueprint.enrichment?.lens?.domain,
      blueprint.enrichment?.lens?.evidenceNoun,
      blueprint.enrichment?.lens?.decisionNoun,
      blueprint.courseModalityProfile?.primaryMode,
      ...(blueprint.courseConcepts || []),
    ].join(' '),
  ).toLowerCase();
}

function isDataScienceBlueprint(blueprint = {}) {
  const text = blueprintDomainText(blueprint);
  return (
    blueprint.courseModalityProfile?.primaryMode === 'data-science-lab' ||
    /\b(applied machine learning|machine learning|data science|data analytics|predictive modeling|classification model|regression model|model validation|train[-\s]?test|cross[-\s]?validation|confusion matrix|jupyter|ipynb|dataframe|sklearn|scikit)\b/.test(
      text,
    ) ||
    (/\b(dataset|data set)\b/.test(text) &&
      /\b(model|prediction|classification|regression|validation|notebook|python|dataframe|machine learning|data science)\b/.test(
        text,
      ))
  );
}

function allowsModelCardLanguage(blueprint = {}) {
  const text = blueprintDomainText(blueprint);
  return (
    isDataScienceBlueprint(blueprint) ||
    (/\b(ai governance|artificial intelligence governance|data ethics|algorithmic accountability|algorithmic bias|model documentation|model cards?|risk management frameworks?|ai procurement|public-sector procurement|vendor claims)\b/.test(
      text,
    ) &&
      /\b(ai|algorithmic|model|governance|data ethics|risk management|procurement)\b/.test(text))
  );
}

function scrubNonDataSlideAssetText(value, blueprint) {
  if (isDataScienceBlueprint(blueprint)) return value;
  let text = String(value);
  text = text
    .replace(/\bdata[-\s]?science notebook\b/gi, 'applied artifact')
    .replace(/\bdata-science-notebook\b/gi, 'applied-artifact')
    .replace(/\bstarter notebooks?\b/gi, 'starter worksheets')
    .replace(/\bJupyter notebooks?\b/gi, 'course workspaces')
    .replace(/\bJupyter\b/gi, 'course workspace')
    .replace(/\bIPYNB\b/gi, 'course worksheet');
  if (!allowsModelCardLanguage(blueprint)) {
    text = text.replace(/\bmodel[-\s]cards\b/gi, 'review notes').replace(/\bmodel[-\s]card\b/gi, 'review note');
  }
  return text;
}

function scrubNonDataSlideAssets(value, blueprint) {
  if (isDataScienceBlueprint(blueprint)) return value;
  if (typeof value === 'string') return scrubNonDataSlideAssetText(value, blueprint);
  if (Array.isArray(value)) return value.map((item) => scrubNonDataSlideAssets(item, blueprint));
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([key, entry]) => [key, scrubNonDataSlideAssets(entry, blueprint)]),
    );
  }
  return value;
}

function compactList(values, fallback = 'source evidence', limit = 3) {
  const items = unique(values, limit);
  return items.length > 0 ? items.join(', ') : fallback;
}

function compactSourceCue(value, fallback = 'assigned source materials', maxWords = 6) {
  const text = stripTerminalPunctuation(cleanText(value, fallback));
  if (!text) return fallback;
  if (isPromptArtifactEvidenceCue(text) || isCompactNumberedArtifactList(text)) return fallback;
  const clauses = text
    .split(/\s*(?:[;|\n,]|\/)\s*/g)
    // A clause carved from the middle of a list keeps its conjunction
    // ("and interpretation quality") — strip it so the cue never leads
    // with a dangling connective.
    .map((part) => stripTerminalPunctuation(cleanText(part)).replace(/^(?:and|or|then|also|plus)\s+/i, ''))
    .filter((part) => part && !isPromptArtifactEvidenceCue(part) && !isCompactNumberedArtifactList(part));
  const boundedClause = clauses.find((part) => {
    const count = wordCount(part);
    return count >= 3 && count <= maxWords;
  });
  if (boundedClause) return boundedClause;
  // No single clause is bounded: prefer the LEADING clauses joined up to the
  // word budget over a mid-list fragment — "Assess test fit, assumption
  // checking, and interpretation quality" should cue "test fit, assumption
  // checking", not "interpretation quality". The head of the list is where
  // the source put the primary signal.
  if (clauses.length > 1) {
    const joined = [];
    let joinedWords = 0;
    for (const clause of clauses) {
      const count = wordCount(clause);
      if (joinedWords + count > maxWords) break;
      joined.push(clause);
      joinedWords += count;
    }
    if (joined.length > 0 && joinedWords >= 3) return joined.join(', ');
  }
  const words = text
    .replace(/[^\w\s.-]+/g, ' ')
    .split(/\s+/)
    .map((word) => word.trim())
    .filter((word) => word && !/^(?:and|or|the|a|an)$/i.test(word));
  if (words.length <= maxWords) return words.join(' ') || text;
  return words.slice(0, maxWords).join(' ');
}

function compactFallbackEvidencePacket(title, lessonNumber) {
  const focus = compactSourceCue(stripLessonPrefix(title), `Lesson ${lessonNumber} source`, 4);
  return `${focus} source packet`;
}

const PROMPT_ARTIFACT_EVIDENCE_LABELS = [
  'course map',
  'syllabus',
  'evidence-rich lesson plans',
  'lesson plans',
  'lesson objectives',
  'learning objectives',
  'slide decks',
  'assignment briefs',
  'assignments',
  'rubric-driven assignments',
  'rubrics',
  'discussion prompts',
  'scenario quizzes',
  'quizzes',
  'quiz and exam bank',
  'quiz bank',
  'study guides',
  'course faq',
  'final capstone presentation',
  'capstone presentation',
  'existing course map fields',
  'worked examples',
  'misconceptions',
  'instructor handoff notes',
];
const PROMPT_ARTIFACT_EVIDENCE_SET = new Set(PROMPT_ARTIFACT_EVIDENCE_LABELS);
const INTERNAL_SOURCE_PLACEHOLDER_RE =
  /\b(?:existing course map fields?|source review rows?|instructor source review|instructor-approved readings|repaired package requires review|no source ledger|prerequisite concept)\b/i;

function normalizePromptArtifactEvidenceCue(value) {
  return cleanText(value)
    .replace(/^(?:lesson|week|module|unit|session)\s*\d{1,3}\s*[:.-]?\s*/i, '')
    .replace(/^\d+(?:\.\d+)*\s*[:.)-]\s*/i, '')
    .replace(/[^\w& -]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function countPromptArtifactEvidenceLabels(value) {
  const normalized = normalizePromptArtifactEvidenceCue(value);
  if (!normalized) return 0;
  let count = 0;
  for (const label of PROMPT_ARTIFACT_EVIDENCE_SET) {
    const pattern = new RegExp(`(?:^|\\b)${escapeRegexLiteral(label)}(?:\\b|$)`, 'i');
    if (pattern.test(normalized)) count += 1;
  }
  return count;
}

function isPromptArtifactEvidenceCue(value) {
  const normalized = normalizePromptArtifactEvidenceCue(value);
  if (!normalized) return false;
  if (INTERNAL_SOURCE_PLACEHOLDER_RE.test(normalized)) return true;
  if (PROMPT_ARTIFACT_EVIDENCE_SET.has(normalized)) return true;
  if (/^weekly assessment\b/i.test(normalized) && countPromptArtifactEvidenceLabels(normalized) >= 1) return true;
  return countPromptArtifactEvidenceLabels(normalized) >= 2;
}

function isCompactNumberedArtifactList(value) {
  const text = cleanText(value);
  if (!text) return false;
  const numberedMarkers = text.match(/\s\d{1,2}[.)]\s+/g) || [];
  if (numberedMarkers.length >= 2) return true;
  if (numberedMarkers.length === 0) return false;
  const normalized = normalizePromptArtifactEvidenceCue(text);
  const artifactishTerms = [
    'quiz',
    'quizzes',
    'assignment',
    'assignments',
    'rubric',
    'rubrics',
    'presentation',
    'presentations',
    'capstone',
    'prompt',
    'prompts',
    'guide',
    'guides',
    'bank',
    'faq',
    'brief',
    'briefs',
    'deck',
    'decks',
  ];
  return artifactishTerms.filter((term) => new RegExp(`\\b${term}\\b`, 'i').test(normalized)).length >= 2;
}

function isPromptArtifactConceptLabel(value) {
  const normalized = normalizePromptArtifactEvidenceCue(value);
  if (!normalized) return false;
  return /^(?:course map|syllabus|lesson objectives?|learning objectives?)$|^(?:scenario\s+)?quizzes?$|^(?:rubric[-\s]?driven\s+)?assignments?$|^rubrics?$|^assignment briefs?$|^(?:quiz\s+(?:and|&)\s+exam\s+bank|quiz bank)$|^(?:final\s+)?capstone presentations?$|^(?:final\s+)?capstone presentation$|^slide decks?$|^lesson plans?$|^discussion prompts?$|^study guides?$|^course faq$|^worked examples?$|^misconceptions?$/i.test(
    normalized,
  );
}

function isUnsafeLessonConceptPhrase(value) {
  return (
    isPromptArtifactEvidenceCue(value) || isPromptArtifactConceptLabel(value) || isCompactNumberedArtifactList(value)
  );
}

const GENERIC_ARTIFACT_LABEL_RE =
  /\b(?:the\s+)?(?:week|lesson|module|unit|session)\s+\d{1,3}(?:\s+[a-z][a-z-]*){0,3}\s+(?:artifact|assessment|assignment|work|submission|deliverable)\b/i;
const GENERIC_ARTIFACT_LABEL_GLOBAL_RE =
  /\b(?:the\s+)?(?:week|lesson|module|unit|session)\s+\d{1,3}(?:\s+[a-z][a-z-]*){0,3}\s+(?:artifact|assessment|assignment|work|submission|deliverable)\b/gi;
const PROMPT_LABELED_ARTIFACT_RE =
  /\b(?:discussion prompts?|quiz(?:zes)?|quiz\s*(?:&|and)\s*exam\s*bank|assignment briefs?|rubric-driven assignments?|rubrics?|slide decks?|study guides?|course faq|lesson plans?)\s*:(?!\s*(?:redirect|revise|review|use|confirm|ask|have|require|collect|seed|mark|watch|catch|press|students?|drafts?|teams?)\b)\s*[^.;,\n\r—-]{2,80}(?=\s+(?:evidence|shows?|begins?|starts?|supports?|requires?|using|from|into|through|before|after|to|for)\b|[.;,\n\r—-]|$)/i;
const PROMPT_LABELED_ARTIFACT_GLOBAL_RE =
  /\b(?:discussion prompts?|quiz(?:zes)?|quiz\s*(?:&|and)\s*exam\s*bank|assignment briefs?|rubric-driven assignments?|rubrics?|slide decks?|study guides?|course faq|lesson plans?)\s*:(?!\s*(?:redirect|revise|review|use|confirm|ask|have|require|collect|seed|mark|watch|catch|press|students?|drafts?|teams?)\b)\s*[^.;,\n\r—-]{2,80}(?=\s+(?:evidence|shows?|begins?|starts?|supports?|requires?|using|from|into|through|before|after|to|for)\b|[.;,\n\r—-]|$)/gi;

function isGenericArtifactLabel(value) {
  return GENERIC_ARTIFACT_LABEL_RE.test(cleanText(value));
}

function isUnsafeLessonArtifactPhrase(value) {
  const text = cleanText(value);
  return isPromptArtifactEvidenceCue(text) || isCompactNumberedArtifactList(text) || isGenericArtifactLabel(text);
}

const COURSE_FAQ_INTERNAL_SCAFFOLD_RE =
  /\b(?:weekly assessment|source packet|source artifacts?|anchor contrast|visual guidance|accessibility description)\b/i;

function isUnsafeCourseFaqPhrase(value) {
  return (
    isUnsafeLessonConceptPhrase(value) ||
    isUnsafeLessonArtifactPhrase(value) ||
    COURSE_FAQ_INTERNAL_SCAFFOLD_RE.test(cleanText(value))
  );
}

const DANGLING_TAIL_RE =
  /(?:\s+(?:and|or|but|for|in|of|to|the|a|an|with|into|onto|from|on|at|by|that|which|as|before|after|around|between|against|toward|towards|about|through|will|should|must|can|their|its|this|these|those|when|while|where|whether|because|so|than|then|also|both|each|per|via|plus|aligned|using)|[,:;–—-])+$/i;

function trimDanglingTail(value) {
  let text = cleanText(value);
  let previous;
  do {
    previous = text;
    text = text.replace(DANGLING_TAIL_RE, '').trim();
  } while (text && text !== previous);
  return text;
}

function conciseClause(value, fallback = 'source evidence', maxLength = 120, { ellipsis = false } = {}) {
  const firstItem = splitList(value)[0] || cleanText(value, fallback);
  const text = stripTerminalPunctuation(firstItem || fallback);
  if (text.length <= maxLength) return text;
  // v0.14.1 slide path: a cut bullet must read as deliberately shortened, not
  // accidentally chopped ("…course pattern: run"). Back up to the last clause
  // boundary when one keeps enough of the budget; otherwise mark the cut with
  // an ellipsis so content verbs never strand at the end of a display bullet.
  if (ellipsis) {
    const slice = text.slice(0, maxLength);
    const sentenceEnd = Math.max(
      slice.lastIndexOf('.'),
      slice.lastIndexOf('!'),
      slice.lastIndexOf('?'),
      slice.lastIndexOf(';'),
    );
    if (sentenceEnd >= Math.floor(maxLength * 0.6)) {
      return cleanText(slice.slice(0, sentenceEnd + 1));
    }
    const clauseEnd = slice.lastIndexOf(',');
    if (clauseEnd >= Math.floor(maxLength * 0.6)) {
      const clause = trimDanglingTail(stripTerminalPunctuation(slice.slice(0, clauseEnd)));
      if (clause) return `${clause}…`;
    }
    const wordCut = trimDanglingTail(stripTerminalPunctuation(slice.replace(/\s+\S*$/g, '')));
    return wordCut ? `${wordCut}…` : fallback;
  }
  // Prefer ending on a clause boundary; otherwise cut at a word boundary and
  // trim any dangling connective so the clause still reads as complete.
  const slice = text.slice(0, maxLength);
  const clauseEnd = Math.max(slice.lastIndexOf(','), slice.lastIndexOf(';'));
  if (clauseEnd >= Math.floor(maxLength * 0.6)) {
    return trimDanglingTail(stripTerminalPunctuation(slice.slice(0, clauseEnd))) || fallback;
  }
  const wordCut = slice.replace(/\s+\S*$/g, '');
  // v0.12.1: a word-boundary cut can still strand a phrase head ("…inspect
  // in Instructor-provided" — 62 hits in the v0.12 audit, because the final
  // token is a content word the dangling-tail pass keeps). Back up to before
  // the last connective when it strands 1–3 trailing tokens, so the kept
  // clause ends on a complete phrase.
  const strandedPhrase = wordCut.match(
    /^(.+)\s(?:and|or|but|for|in|of|to|the|a|an|with|into|onto|from|on|at|by|that|which|as|before|after|around|between|against|toward|towards|about|through|when|while|where|whether|because|so|than|then|using|aligned)(?:\s\S+){1,3}$/i,
  );
  const candidate =
    strandedPhrase && strandedPhrase[1].length >= Math.floor(maxLength * 0.5) ? strandedPhrase[1] : wordCut;
  return trimDanglingTail(stripTerminalPunctuation(candidate)) || fallback;
}

function customPracticeContext(blueprint, lens) {
  const courseText = cleanText(
    [
      blueprint?.courseName,
      ...(blueprint?.lessons || []).flatMap((lesson) => [lesson?.title, ...(lesson?.keyConcepts || [])]),
    ].join(' '),
  ).toLowerCase();
  const domain = cleanText(lens?.domain, 'course work');
  if (
    /community health evaluation/i.test(domain) &&
    !/\b(community health|public health|healthcare|health care)\b/i.test(courseText)
  ) {
    return 'your course-specific work';
  }
  if (/\b(work|practice|lab|studio|seminar|workshop|placement|rehearsal)\b/i.test(domain)) return `your ${domain}`;
  return `your ${domain} work`;
}

function alternateLessonConcept(lesson, primary) {
  const generic = new Set(['clinical', 'community', 'health', 'studio', 'lesson', 'topic', 'block']);
  const primaryKey = cleanText(primary).toLowerCase();
  const safeConcepts = safeLessonConcepts(lesson, { limit: 8 }).filter((concept) => {
    const normalized = cleanText(concept).toLowerCase();
    return normalized && normalized !== primaryKey;
  });
  return safeConcepts.find((concept) => !generic.has(cleanText(concept).toLowerCase())) || safeConcepts[0] || primary;
}

